 1	#!/usr/bin/env bats
 2	# Path-scoped rule files (grimoires/loa/sdd.md D-3.1, DEC-0129): stash-safety.md and
 3	# skill-invariants.md carry `paths:` frontmatter, the frontmatter parses, and every glob
 4	# matches at least one tracked file of the kind the rule is about (git pathspec glob
 5	# semantics: `**` spans directories, `*` stays inside one).
 6	
 7	setup() {
 8	    PROJECT_ROOT="$(cd "${BATS_TEST_DIRNAME}/../.." && pwd)"
 9	    RULES="$PROJECT_ROOT/.claude/rules"
10	    command -v yq >/dev/null 2>&1 || skip "yq not installed"
11	}
12	
13	# The YAML between the first two '---' lines (empty when the file has none).
14	frontmatter() { awk 'NR == 1 && $0 != "---" { exit } /^---$/ { if (n++) exit; next } n' "$1"; }
15	globs() { frontmatter "$1" | yq eval '.paths[]' -; }
16	tracked() { git -C "$PROJECT_ROOT" ls-files -- ":(glob)$1"; }
17	
18	@test "RP-1 both rule files open with frontmatter that parses and lists string globs under paths:" {
19	    local f n
20	    for f in stash-safety.md skill-invariants.md; do
21	        [ "$(head -1 "$RULES/$f")" = "---" ] || { echo "$f has no frontmatter"; return 1; }
22	        frontmatter "$RULES/$f" | yq eval '.' - >/dev/null || { echo "$f frontmatter does not parse"; return 1; }
23	        [ "$(frontmatter "$RULES/$f" | yq eval '.paths | type' -)" = "!!seq" ]
24	        n="$(frontmatter "$RULES/$f" | yq eval '.paths | length' -)"
25	        [ "$n" -ge 1 ]
26	        [ "$(frontmatter "$RULES/$f" | yq eval '[.paths[] | select(type != "!!str")] | length' -)" -eq 0 ]
27	    done
28	}
29	
30	@test "RP-2 the globs are the ones the SDD names" {
31	    [ "$(globs "$RULES/stash-safety.md" | tr '\n' ' ')" = '**/*.sh **/*.bats .claude/scripts/** .claude/hooks/** ' ]
32	    [ "$(globs "$RULES/skill-invariants.md" | tr '\n' ' ')" = '.claude/skills/**/SKILL.md .claude/agents/** .claude/data/agent-types.yaml .claude/scripts/validate-skill-capabilities.sh ' ]
33	}
34	
35	@test "RP-3 every stash-safety glob matches a tracked shell source" {
36	    local g hits
37	    while IFS= read -r g; do
38	        hits="$(tracked "$g" | grep -E '\.(sh|bats)$' | head -1)"
39	        [ -n "$hits" ] || { echo "glob '$g' matches no tracked .sh/.bats file"; return 1; }
40	    done < <(globs "$RULES/stash-safety.md")
41	}
42	
43	@test "RP-4 every skill-invariants glob matches a tracked skill, agent definition or capability file" {
44	    local g hits
45	    while IFS= read -r g; do
46	        hits="$(tracked "$g" | grep -E '(^\.claude/skills/[^/]+/SKILL\.md$|^\.claude/agents/[^/]+\.md$|^\.claude/data/agent-types\.yaml$|^\.claude/scripts/validate-skill-capabilities\.sh$)' | head -1)"
47	        [ -n "$hits" ] || { echo "glob '$g' matches no tracked file of the intended kind"; return 1; }
48	    done < <(globs "$RULES/skill-invariants.md")
49	}
50	
51	@test "RP-5 path-scoping removed no rule text: the body after the frontmatter keeps its heading and sections" {
52	    local body
53	    body="$(awk '/^---$/ && c < 2 { c++; next } c >= 2' "$RULES/stash-safety.md")"
54	    [[ "$body" == *"# Git Stash Safety"* && "$body" == *"## Judgment rules the fence cannot express"* ]]
55	    body="$(awk '/^---$/ && c < 2 { c++; next } c >= 2' "$RULES/skill-invariants.md")"
56	    [[ "$body" == *"# Skill Frontmatter Invariants"* && "$body" == *"## The invariant"* ]]
57	}
58	
59	@test "RP-6 the rule-lifecycle validator accepts both files (origin, version, enacted_by)" {
60	    run "$PROJECT_ROOT/.claude/scripts/validate-rule-lifecycle.sh" --json
61	    [ "$status" -eq 0 ] || { echo "$output"; return 1; }
62	}

